sp_widget.css:
/* =========================================================
   GATENOW LANDING · APPLICATION PROCESS
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   Design notes worth keeping:

   1. No form inputs. An earlier version used radio buttons for
      state, and the portal theme styled them into view as a row
      of circles. Hover and focus carry the state instead, so
      there is nothing for a theme to fight over.

   2. Each panel sits inside its own row in the markup so the
      reveal is a plain descendant selector, then is positioned
      into the right hand column. The column widths are fixed
      percentages rather than fr units so the panel can be
      placed against them precisely.

   3. Step 01 is open by default. Hovering the list hides it and
      shows whichever row is under the pointer.

   4. Reveals use transitions, not keyframes, so a hover that
      leaves halfway reverses smoothly instead of snapping.
   ========================================================= */

/* ---------- typeface ----------
   Shared with the hero and About widgets. If they sit on one
   page, keep a single copy in a Style Sheet record attached to
   the theme and delete this block from the widgets.
   ------------------------------------------------------------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- palette ---------- */
$gnp-navy:      #0a2540;
$gnp-blue:      #1560e0;
$gnp-blue-dk:   #0f4cbb;
$gnp-blue-soft: #eef3fd;
$gnp-body:      #55677f;
$gnp-hair:      #e2e9f4;
$gnp-white:     #ffffff;

$gnp-ease:      cubic-bezier(0.45, 0.05, 0.25, 1);

/* the detail column starts here. changing this one number moves
   the split, the panels follow it. */
$gnp-split:     45%;
$gnp-gap:       12px;

$gnp-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   BAND
   ========================================================= */

.gnp-process {
  position: relative;
  width: 100%;
  padding: 106px 24px 114px;
  font-family: $gnp-font;
  color: $gnp-navy;
  background-color: #eef4fd;
  background-image:
    radial-gradient(860px 520px at 50% -6%, rgba(21, 96, 224, 0.08), rgba(21, 96, 224, 0) 66%),
    linear-gradient(180deg, #f3f7fe 0%, #e9f1fd 52%, #f3f7fe 100%);
}

.gnp-process *,
.gnp-process *::before,
.gnp-process *::after { box-sizing: border-box; }

.gnp-process__inner {
  position: relative;
  max-width: 1120px;
  margin: 0 auto;
}


/* =========================================================
   HEADER
   ========================================================= */

.gnp-head {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}

.gnp-process .gnp-eyebrow {
  display: inline-flex;
  align-items: center;
  padding: 8px 18px;
  margin: 0 0 22px;
  border-radius: 999px;
  background: $gnp-blue-soft;
  color: $gnp-blue;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.gnp-process .gnp-heading {
  margin: 0;
  font-size: 48px;
  font-weight: 700;
  line-height: 1.14;
  letter-spacing: -0.03em;
  color: $gnp-navy;
}

@supports (font-size: clamp(30px, 3.7vw, 48px)) {
  .gnp-process .gnp-heading { font-size: clamp(30px, 3.7vw, 48px); }
}

.gnp-process .gnp-sub {
  max-width: 620px;
  margin: 20px auto 0;
  padding: 0;
  font-size: 17.5px;
  font-weight: 400;
  line-height: 1.64;
  color: $gnp-body;
}


/* =========================================================
   BOARD
   ========================================================= */

.gnp-board {
  position: relative;
  margin-top: 54px;
  padding: 12px;
  border-radius: 30px;
  background: rgba(255, 255, 255, 0.62);
  border: 1px solid rgba(255, 255, 255, 0.92);
  box-shadow: 0 30px 70px rgba(16, 54, 110, 0.10);
}

.gnp-cols {
  position: relative;
  display: grid;
  grid-template-columns: $gnp-split minmax(0, 1fr);
  gap: $gnp-gap;
  align-items: stretch;
}


/* ---------- index ---------- */

.gnp-list {
  padding: 22px 14px 24px;
  border-radius: 22px;
  background: $gnp-white;
}

.gnp-group + .gnp-group { margin-top: 22px; }

.gnp-process .gnp-group__label {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0 0 10px;
  padding: 0 14px;
}

.gnp-group__name {
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: $gnp-blue;
}

.gnp-group__note {
  font-size: 12.5px;
  color: rgba(85, 103, 127, 0.85);
}

/* deliberately not position relative. The panel inside each row
   is absolutely positioned against .gnp-cols so it lands in the
   detail column. Making the row a positioning context would trap
   the panel inside the row, which is exactly what it did before. */
.gnp-item {
  position: static;
  display: block;
  padding: 0;
  border-radius: 14px;
  cursor: default;
  outline: none;
  transition: background 0.45s $gnp-ease;
}

/* the whole row shares one grid, so numbers and titles line up
   down the list regardless of title length */
.gnp-item__row {
  position: relative;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) 18px;
  align-items: center;
  gap: 14px;
  padding: 11px 14px;
}

.gnp-item__bar {
  position: absolute;
  top: 9px;
  bottom: 9px;
  left: 0;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: $gnp-blue;
  z-index: 1;
  transform: scaleY(0);
  transform-origin: center;
  transition: transform 0.45s $gnp-ease;
}

.gnp-item__num {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 32px;
  border-radius: 9px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.05em;
  transition: background 0.45s $gnp-ease,
              color 0.45s $gnp-ease,
              border-color 0.45s $gnp-ease;
}

/* filled, the applicant holds this step */
.gnp-item--you .gnp-item__num {
  background: rgba(21, 96, 224, 0.12);
  border: 1px solid transparent;
  color: $gnp-blue;
}

/* outlined, it sits with someone else */
.gnp-item--them .gnp-item__num {
  background: $gnp-white;
  border: 1px solid rgba(10, 37, 64, 0.2);
  color: rgba(10, 37, 64, 0.6);
}

.gnp-item__title {
  min-width: 0;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.4;
  letter-spacing: -0.01em;
  color: $gnp-navy;
  transition: color 0.45s $gnp-ease;
}

.gnp-item__go {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  font-size: 15px;
  color: $gnp-blue;
  opacity: 0;
  transform: translateX(-6px);
  transition: opacity 0.45s $gnp-ease, transform 0.45s $gnp-ease;
}


/* ---------- detail column ---------- */

.gnp-canvas {
  position: relative;
  grid-column: 2;
  min-height: 420px;
  border-radius: 22px;
  overflow: hidden;
  background:
    radial-gradient(520px 320px at 100% 0%, rgba(21, 96, 224, 0.10), rgba(21, 96, 224, 0) 68%),
    linear-gradient(150deg, #ffffff 0%, #f7faff 100%);
}

.gnp-canvas__hint {
  position: absolute;
  right: 26px;
  bottom: 22px;
  font-size: 12.5px;
  letter-spacing: 0.02em;
  color: rgba(85, 103, 127, 0.6);
  transition: opacity 0.45s $gnp-ease;
}

.gnp-list:hover ~ .gnp-canvas .gnp-canvas__hint { opacity: 0; }

/* panels are written inside their row, then placed over the
   canvas. left matches the split plus the grid gap exactly. */
.gnp-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc(#{$gnp-split} + #{$gnp-gap});
  right: 0;
  display: flex;
  align-items: center;
  padding: 38px 40px 34px;
  border-radius: 22px;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
  transform: translateY(10px);
  transition: opacity 0.5s $gnp-ease, transform 0.6s $gnp-ease;
  z-index: 2;
}

.gnp-panel__body {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 540px;
}

.gnp-panel__ghost {
  position: absolute;
  top: 22px;
  right: 30px;
  z-index: 1;
  font-size: 104px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.05em;
  color: rgba(21, 96, 224, 0.07);
  pointer-events: none;
  transform: translateX(18px);
  transition: transform 0.7s $gnp-ease;
}

.gnp-panel__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-bottom: 20px;
}

.gnp-panel__phase {
  display: inline-flex;
  align-items: center;
  height: 28px;
  padding: 0 13px;
  border-radius: 999px;
  background: $gnp-navy;
  color: $gnp-white;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.gnp-panel__owner {
  display: inline-flex;
  align-items: center;
  height: 28px;
  gap: 8px;
  padding: 0 14px;
  border-radius: 999px;
  background: $gnp-blue-soft;
  color: $gnp-blue-dk;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.05em;
}

.gnp-panel__dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
}

.gnp-panel--you .gnp-panel__dot { background: $gnp-blue; }

.gnp-panel--them .gnp-panel__dot {
  background: $gnp-white;
  border: 2px solid rgba(10, 37, 64, 0.34);
}

.gnp-panel--them .gnp-panel__owner {
  background: rgba(10, 37, 64, 0.06);
  color: rgba(10, 37, 64, 0.66);
}

.gnp-process .gnp-panel__title {
  margin: 0;
  max-width: 460px;
  font-size: 30px;
  font-weight: 600;
  line-height: 1.22;
  letter-spacing: -0.028em;
  color: $gnp-navy;
}

@supports (font-size: clamp(22px, 2.3vw, 30px)) {
  .gnp-process .gnp-panel__title { font-size: clamp(22px, 2.3vw, 30px); }
}

.gnp-process .gnp-panel__text {
  margin: 16px 0 0;
  padding: 0;
  font-size: 16.5px;
  font-weight: 400;
  line-height: 1.72;
  color: $gnp-body;
}

.gnp-process .gnp-panel__foot {
  margin: 22px 0 0;
  padding: 16px 0 0;
  border-top: 1px solid $gnp-hair;
  font-size: 14.5px;
  font-style: italic;
  color: rgba(85, 103, 127, 0.88);
}

.gnp-process .gnp-close {
  max-width: 620px;
  margin: 32px auto 0;
  padding: 0;
  text-align: center;
  font-size: 15px;
  color: rgba(85, 103, 127, 0.9);
}


/* =========================================================
   REVEAL
   Step 01 is the resting state. Hovering the list retires it
   and whichever row is under the pointer takes over. Focus
   mirrors hover so the section works from the keyboard.
   ========================================================= */

.gnp-item--1 .gnp-panel {
  opacity: 1;
  transform: translateY(0);
}

.gnp-item--1 .gnp-panel .gnp-panel__ghost { transform: translateX(0); }

.gnp-list:hover .gnp-item--1 .gnp-panel {
  opacity: 0;
  transform: translateY(10px);
}

.gnp-item:hover .gnp-panel,
.gnp-item:focus .gnp-panel,
.gnp-item:focus-within .gnp-panel {
  opacity: 1;
  transform: translateY(0);
}

/* Step 01 needs its own rule. The rule above scores two classes,
   while .gnp-list:hover .gnp-item--1 .gnp-panel scores three, so
   without this the first step would go blank on hover while every
   other step worked. */
.gnp-list:hover .gnp-item--1:hover .gnp-panel,
.gnp-list:hover .gnp-item--1:focus .gnp-panel,
.gnp-list:hover .gnp-item--1:focus-within .gnp-panel {
  opacity: 1;
  transform: translateY(0);
}

.gnp-list:hover .gnp-item--1:hover .gnp-panel__ghost,
.gnp-list:hover .gnp-item--1:focus .gnp-panel__ghost {
  transform: translateX(0);
}

.gnp-item:hover .gnp-panel__ghost,
.gnp-item:focus .gnp-panel__ghost {
  transform: translateX(0);
}

.gnp-item:hover,
.gnp-item:focus {
  background: rgba(21, 96, 224, 0.06);
}

.gnp-item:hover .gnp-item__bar,
.gnp-item:focus .gnp-item__bar { transform: scaleY(1); }

.gnp-item:hover .gnp-item__title,
.gnp-item:focus .gnp-item__title { color: $gnp-blue-dk; }

.gnp-item:hover .gnp-item__num,
.gnp-item:focus .gnp-item__num {
  background: $gnp-blue;
  border-color: $gnp-blue;
  color: $gnp-white;
}

.gnp-item:hover .gnp-item__go,
.gnp-item:focus .gnp-item__go {
  opacity: 1;
  transform: translateX(0);
}

.gnp-item:focus {
  box-shadow: 0 0 0 2px $gnp-blue;
}


/* =========================================================
   MOTION ON LOAD
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gnpFade {
    from { opacity: 0; transform: translateY(16px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  .gnp-process .gnp-eyebrow,
  .gnp-process .gnp-heading,
  .gnp-process .gnp-sub,
  .gnp-board,
  .gnp-process .gnp-close {
    animation: gnpFade 0.72s $gnp-ease backwards;
  }

  .gnp-process .gnp-heading { animation-delay: 0.08s; }
  .gnp-process .gnp-sub     { animation-delay: 0.16s; }
  .gnp-board                { animation-delay: 0.26s; }
  .gnp-process .gnp-close   { animation-delay: 0.38s; }
}


/* =========================================================
   RESPONSIVE
   There is no hover on touch, so below the breakpoint every
   panel opens inline under its own row and the detail column
   is dropped.
   ========================================================= */

@media (max-width: 980px) {

  .gnp-process { padding: 82px 20px 90px; }

  .gnp-board { margin-top: 42px; }

  .gnp-cols { grid-template-columns: minmax(0, 1fr); }

  .gnp-canvas { display: none; }

  .gnp-item:hover,
  .gnp-item:focus { background: transparent; }

  .gnp-item__go { display: none; }

  .gnp-item__row { grid-template-columns: 42px minmax(0, 1fr); }

  .gnp-panel {
    position: static;
    display: block;
    opacity: 1;
    pointer-events: auto;
    transform: none;
    padding: 0 14px 20px 70px;
    border-radius: 0;
  }

  .gnp-list:hover .gnp-item--1 .gnp-panel {
    opacity: 1;
    transform: none;
  }

  .gnp-panel__ghost { display: none; }

  .gnp-panel__body { max-width: none; }

  .gnp-panel__meta { margin-bottom: 12px; }

  .gnp-process .gnp-panel__title {
    font-size: 19px;
    max-width: none;
  }

  .gnp-process .gnp-panel__text { font-size: 15.5px; margin-top: 10px; }
  .gnp-process .gnp-panel__foot { margin-top: 14px; padding-top: 12px; }

  /* the row title would repeat the panel title at this width */
  .gnp-item__title { display: none; }

  .gnp-item__row { grid-template-columns: 42px minmax(0, 1fr); padding-bottom: 4px; }
}

@media (max-width: 620px) {

  .gnp-process { padding: 60px 16px 68px; }

  .gnp-board { padding: 8px; border-radius: 24px; }

  .gnp-list { padding: 18px 10px 20px; }

  .gnp-panel { padding: 0 12px 18px 62px; }

  .gnp-process .gnp-sub { font-size: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  .gnp-process * { transition: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW LANDING · APPLICATION PROCESS
     Service Portal widget · Server script

     Copy lives here rather than in the template so every string
     passes through gs.getMessage and stays translatable. No
     table access, so no ACL considerations apply.

     data.phases is the grouped view that drives the list. Each
     step also carries a running number and its phase label,
     added at the bottom of this script, which the panels use.

     Note on option names: every widget instance already has a
     built in "title" field, so options.title returns the
     instance title rather than anything you set. The heading
     option is named heading for that reason. The same applies
     to color, glyph and size.
     ========================================================= */

  function opt(name, fallback) {
    var value = options[name];
    if (value === null || value === undefined || value === '') {
      return fallback;
    }
    return value.toString();
  }

  data.regionLabel = opt('region_label', gs.getMessage('The application process'));
  data.hint        = opt('hint', gs.getMessage('Hover a step to read it'));
  data.eyebrow     = opt('eyebrow', gs.getMessage('The process'));
  data.heading     = opt('heading', gs.getMessage('From open program to closed grant'));

  data.subhead = opt('subhead', gs.getMessage(
    'One lifecycle, two halves. The first decides whether you get the money. ' +
    'The second decides whether the funder ever has to ask you a difficult ' +
    'question about how you spent it.'));

  data.closeLine = opt('close_line', gs.getMessage(
    'Twelve steps, one record. Nothing gets retyped and nothing gets lost between them.'));

  data.phases = [
    {
      key  : 'pre',
      label: gs.getMessage('Pre-award'),
      note : gs.getMessage('Applying and being assessed'),
      steps: [
        {
          index: '01',
          side : 'you',
          owner: gs.getMessage('You'),
          title: gs.getMessage('Pick a program you qualify for'),
          text : gs.getMessage(
            'Every open program publishes its criteria, its funding range and its ' +
            'closing date before it opens. Read those three first. Eligibility ' +
            'rules do not bend later, however good the project is.'),
          foot : gs.getMessage('You will know in a minute, not after a fortnight of drafting.')
        },
        {
          index: '02',
          side : 'you',
          owner: gs.getMessage('You'),
          title: gs.getMessage('Submit the proposal and the paperwork'),
          text : gs.getMessage(
            'Project description, budget and supporting documents go in as one ' +
            'package. An incomplete submission is the most common reason a good ' +
            'idea never reaches a reviewer.'),
          foot : gs.getMessage('Drafts save as you go, so nothing depends on one long sitting.')
        },
        {
          index: '03',
          side : 'them',
          owner: gs.getMessage('Review team'),
          title: gs.getMessage('Screening'),
          text : gs.getMessage(
            'A reviewer checks the application is complete and within scope. Some ' +
            'are declined at this point. If yours is one of them you get the ' +
            'reason, not silence.'),
          foot : gs.getMessage('This is where most applications end. Better to hear it now.')
        },
        {
          index: '04',
          side : 'them',
          owner: gs.getMessage('Review team'),
          title: gs.getMessage('Scoring'),
          text : gs.getMessage(
            'Applications that pass screening are scored against the criteria the ' +
            'program published. Every reviewer works the same scale, so the ranking ' +
            'survives the question of how it was decided.'),
          foot : gs.getMessage('Same scale for everyone, recorded against every application.')
        },
        {
          index: '05',
          side : 'them',
          owner: gs.getMessage('Funding panel'),
          title: gs.getMessage('The decision'),
          text : gs.getMessage(
            'The strongest applications are awarded, each with a grant amount ' +
            'attached. It is not always the figure you asked for, and the reasoning ' +
            'arrives with the offer.'),
          foot : gs.getMessage('The amount and the conditions land together, in writing.')
        },
        {
          index: '06',
          side : 'you',
          owner: gs.getMessage('You'),
          title: gs.getMessage('Accept or decline'),
          text : gs.getMessage(
            'The offer is yours to take or turn down. Acknowledge it and the project ' +
            'opens. Decline it and the record closes cleanly, with the reason on file.'),
          foot : gs.getMessage('Acknowledging the award is what starts the second half.')
        }
      ]
    },
    {
      key  : 'post',
      label: gs.getMessage('Post-award'),
      note : gs.getMessage('Delivering and reporting'),
      steps: [
        {
          index: '07',
          side : 'you',
          owner: gs.getMessage('You'),
          title: gs.getMessage('Set the baseline'),
          text : gs.getMessage(
            'Before any work is reported you file a baseline: the dates, the ' +
            'milestones and the budget you are committing to. Everything after this ' +
            'is measured against it.'),
          foot : gs.getMessage('Filed once, referenced for the rest of the grant.')
        },
        {
          index: '08',
          side : 'you',
          owner: gs.getMessage('You'),
          title: gs.getMessage('Report every month'),
          text : gs.getMessage(
            'A short status report on schedule, cost, resources and scope, rated ' +
            'green, amber or red. Written in the month it happened, not ' +
            'reconstructed from memory in year two.'),
          foot : gs.getMessage('Ten minutes a month beats three days of archaeology later.')
        },
        {
          index: '09',
          side : 'you',
          owner: gs.getMessage('You, approved by the program team'),
          title: gs.getMessage('Raise a change request'),
          text : gs.getMessage(
            'Projects move. When a date, a cost or the scope changes you raise it ' +
            'and have it approved at the time, rather than explaining it in the ' +
            'final report.'),
          foot : gs.getMessage('Approved changes update the plan. Nothing is rewritten quietly.')
        },
        {
          index: '10',
          side : 'you',
          owner: gs.getMessage('You and finance'),
          title: gs.getMessage('Claim your costs back'),
          text : gs.getMessage(
            'Reimbursement requests go in with the evidence attached, and you can ' +
            'follow each one through review to payment. Every claim traces back to a ' +
            'line in the awarded budget.'),
          foot : gs.getMessage('You can see which claims are paid, in review, or waiting on you.')
        },
        {
          index: '11',
          side : 'them',
          owner: gs.getMessage('Project manager'),
          title: gs.getMessage('Risks and issues get raised, not buried'),
          text : gs.getMessage(
            'The project manager logs anything that could derail delivery. You ' +
            'confirm what is actually happening on the ground, and it stays open ' +
            'until it is resolved.'),
          foot : gs.getMessage('Nothing sits in someone\'s head waiting to become a surprise.')
        },
        {
          index: '12',
          side : 'them',
          owner: gs.getMessage('Project and program managers'),
          title: gs.getMessage('Delivered, then closed'),
          text : gs.getMessage(
            'When the work is finished it is checked against what was funded. If the ' +
            'two line up the grant moves to closed, and the whole history stays on ' +
            'the record behind it.'),
          foot : gs.getMessage('Closed means finished and evidenced, not just finished.')
        }
      ]
    }
  ];

  /* running number across both phases, plus the phase label each
     step belongs to, used by the detail panels */
  var n = 0;

  for (var i = 0; i < data.phases.length; i++) {
    for (var j = 0; j < data.phases[i].steps.length; j++) {
      n++;
      data.phases[i].steps[j].n = n;
      data.phases[i].steps[j].phase = data.phases[i].label;
    }
  }

})();
